/**
 * Get the URL for the previous request.
 *
 * @param  mixed  $fallback
 * @return string
 */
public function previous($fallback = false)
{
    $request = $this->request;

    $referrer = $request->header('referer');

    $scheme = $request->getScheme();
    $httpHost = $request->getHttpHost();
    $baseUrl = $request->getBaseUrl();
    $pathInfo = $request->getPathInfo();
    $requestUri = $request->getRequestUri();
    $queryString = $request->getQueryString() ?? parse_url($requestUri, PHP_URL_QUERY);
    $queryData = $request->query();

    if (! $queryString && $queryData) {
        $queryString = http_build_query($queryData);
    }

    $question = $baseUrl.$pathInfo === '/' ? '/?' : '?';
    $currentUrl = $scheme.'://'.$httpHost.$baseUrl.$pathInfo.($queryString ? $question.$queryString : '');
    $computedRoot = rtrim(preg_replace('/\?.*/', '', $currentUrl), '/');

    if ($pathInfo && $pathInfo !== '/') {
        $computedRoot = str_ends_with($computedRoot, $pathInfo)
            ? rtrim(substr($computedRoot, 0, -strlen($pathInfo)), '/')
            : $computedRoot;
    }

    if ($referrer) {
        if ($this->isValidUrl($referrer)) {
            $url = $referrer;
        } else {
            $root = $this->formatRoot($this->formatScheme(), $this->forcedRoot ?: $computedRoot);
            [$path, $query] = $this->extractQueryString($referrer);

            $url = $this->format($root, '/'.trim($path.'/', '/')).$query;
        }
    } else {
        $url = $this->getPreviousUrlFromSession();
    }

    if ($url) {
        return $url;
    } elseif ($fallback) {
        return $this->to($fallback);
    }

    return $this->to('/');
}

/**
 * Get the previous path info for the request.
 *
 * @param  mixed  $fallback
 * @return string
 */
public function previousPath($fallback = false)
{
    $previousPath = str_replace($this->to('/'), '', rtrim(preg_replace('/\?.*/', '', $this->previous($fallback)), '/'));

    return $previousPath === '' ? '/' : $previousPath;
}

/**
 * Get the previous URL from the session if possible.
 *
 * @return string|null
 */
protected function getPreviousUrlFromSession()
{
    $session = $this->getSession();

    return $session ? $session->previousUrl() : null;
}

